package com.luci.pianoroom;
import java.util.*;
public final class BenchmarkTest {
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 static class Fake implements PianoBenchmark.Driver {int nowBuffer,events,finishes,pedal;int[] held=new int[128];Set<Integer> velocity=new HashSet<>();PianoBenchmark.Metrics m=new PianoBenchmark.Metrics();String report;int recommended;public void buffer(int ms){nowBuffer=ms;m.bufferMs=Math.max(4,ms);m.nativeAudio=true;}public void midi(int s,int k,int v){events++;if(s==0x90){held[k]++;velocity.add(v);}if(s==0x80){check(held[k]>0,"balanced note off");held[k]--;}if(s==0xB0)pedal=v;}public PianoBenchmark.Metrics metrics(){return m.copy();}public void finished(String report,int r){finishes++;this.report=report;recommended=r;}void clear(){check(pedal==0,"released pedal");for(int x:held)check(x==0,"no stuck notes");}}
 public static void main(String[]args){Fake f=new Fake();PianoBenchmark b=new PianoBenchmark(f,new int[]{8,6,4,2},"USB piano");long now=0;b.start(now);for(int phase=0;phase<4;phase++){now+=700;for(int tick=0;tick<96;tick++){b.tick(now);now+=125;}check(b.waiting,"waits for listener rating");f.clear();check(f.velocity.contains(35)&&f.velocity.contains(127)&&f.velocity.size()>30,"varied dynamics");b.rate(phase==3?1:0,now);}check(!b.active&&f.finishes==1&&f.recommended==4&&f.report.contains("aceito 4.00"),"human rating + actual buffer recommendation");
  f=new Fake();b=new PianoBenchmark(f,new int[]{2},"USB");b.start(0);for(int i=0;i<96;i++){if(i==50)f.m.xruns++;b.tick(700+i*125);}b.rate(0,14000);check(f.recommended<0,"good ear rating does not override measured failures");
  f=new Fake();b=new PianoBenchmark(f,new int[]{2},"USB");b.start(0);for(int i=0;i<96;i++){if(i==50)f.m.midiOverflow++;f.m.effectsMs=.4;f.m.sampleMs=.2;b.tick(700+i*125);}b.rate(0,14000);check(f.recommended<0&&f.report.contains("efeitos 0.400")&&f.report.contains("excessos no teste 1"),"MIDI overflow disqualifies recommendation and measured DSP phases survive report");
  f=new Fake();b=new PianoBenchmark(f,new int[]{2},"USB");b.start(0);b.tick(700);b.cancel("exit");b.cancel("again");f.clear();check(f.finishes==1&&!b.active,"idempotent cancellation restore");
  check(AudioHealth.nextBuffer(2,2,1)==4&&AudioHealth.nextBuffer(2,4,1)==6&&AudioHealth.nextBuffer(118,118,8)==120,"small adaptive steps honour accepted buffer");check(AudioHealth.explain(1,0,0,.5f,0).contains("largura de banda MIDI")&&AudioHealth.explain(0,0,0,1.2f,10).contains("volume"),"separate underrun and overload advice");System.out.println("PASS: musical stress sequence, balanced MIDI/pedal, listener ratings, actual/requested buffer distinction, failing-step recommendation excluded, cancel restores once, gradual native buffer adaptation.");
 }
}
